+use std::io::ErrorKind;
+use std::path::{Path, PathBuf};
+
+use callisto_model::ManifestFormat;
+use globset::{GlobBuilder, GlobSet, GlobSetBuilder};
+
+use crate::locate::LocateError;
+
+pub(crate) enum MembershipAuthority<T> {
+    Absent,
+    Present(T),
+}
+
+pub(crate) struct NegatableGlobSet {
+    positive: GlobSet,
+    negative: GlobSet,
+}
+
+impl NegatableGlobSet {
+    pub(crate) fn is_match(&self, path: &Path) -> bool {
+        self.positive.is_match(path) && !self.negative.is_match(path)
+    }
+
+    fn empty() -> Self {
+        Self {
+            positive: GlobSet::empty(),
+            negative: GlobSet::empty(),
+        }
+    }
+}
+
+#[derive(Clone, Copy)]
+struct AuthorityPath {
+    ecosystem: &'static str,
+    path: &'static str,
+}
+
+impl AuthorityPath {
+    fn relative_path(self) -> PathBuf {
+        PathBuf::from(self.path)
+    }
+
+    fn field_error(self, field: &'static str, detail: &'static str) -> LocateError {
+        LocateError::MembershipField {
+            ecosystem: self.ecosystem,
+            path: self.relative_path(),
+            field,
+            detail,
+        }
+    }
+}
