+        Ok(content) => Ok(Some(content)),
+        Err(error) if error.kind() == ErrorKind::NotFound => Ok(None),
+        Err(error) => Err(LocateError::MembershipRead {
+            ecosystem: authority.ecosystem,
+            path: authority.relative_path(),
+            message: error.to_string(),
+        }),
+    }
+}
+
+fn build_globset(
+    entries: &[String],
+    authority: AuthorityPath,
+    field: &'static str,
+) -> Result<NegatableGlobSet, LocateError> {
+    let mut positive = GlobSetBuilder::new();
+    let mut negative = GlobSetBuilder::new();
+    for entry in entries {
+        let (builder, pattern) = match entry.strip_prefix('!') {
+            Some(rest) => (&mut negative, rest),
+            None => (&mut positive, entry.as_str()),
+        };
+        let glob = GlobBuilder::new(pattern)
+            .literal_separator(true)
+            .build()
+            .map_err(|error| LocateError::MembershipGlob {
+                ecosystem: authority.ecosystem,
+                path: authority.relative_path(),
+                field,
+                pattern: entry.clone(),
+                message: error.to_string(),
+            })?;
+        builder.add(glob);
+    }
+    let positive = positive.build().map_err(|error| LocateError::MembershipGlob {
+        ecosystem: authority.ecosystem,
+        path: authority.relative_path(),
+        field,
+        pattern: "<compiled positive set>".to_string(),
+        message: error.to_string(),
+    })?;
+    let negative = negative.build().map_err(|error| LocateError::MembershipGlob {
+        ecosystem: authority.ecosystem,
+        path: authority.relative_path(),
+        field,
+        pattern: "<compiled negative set>".to_string(),
+        message: error.to_string(),
+    })?;
+    Ok(NegatableGlobSet { positive, negative })
+}
+
+pub(crate) struct Membership {
+    members: Option<NegatableGlobSet>,
+    exclude: NegatableGlobSet,
+    hybrid_root: bool,
+}
+
+impl Membership {
+    pub(crate) fn admits(&self, rel: &Path, is_root: bool) -> bool {
+        if is_root && self.hybrid_root {
+            return true;
+        }
+        !self.exclude.is_match(rel) && self.members.as_ref().is_none_or(|members| members.is_match(rel))
+    }
+}
+
+pub(crate) struct MembershipSpec {
+    manifest_file_name: &'static str,
+    table_path: &'static [&'static str],
+    owner_key: &'static str,
+    ecosystem: &'static str,
+}
+
+pub(crate) const CARGO_MEMBERSHIP_SPEC: MembershipSpec = MembershipSpec {
+    manifest_file_name: ManifestFormat::CargoToml.file_name(),
+    table_path: &["workspace"],
+    owner_key: "package",
+    ecosystem: "Cargo",
+};
+
+pub(crate) const PYTHON_MEMBERSHIP_SPEC: MembershipSpec = MembershipSpec {
+    manifest_file_name: ManifestFormat::PyprojectToml.file_name(),
+    table_path: &["tool", "uv", "workspace"],
+    owner_key: "project",
+    ecosystem: "uv",
+};
